import { describe, expect, it } from 'vitest';
import { buildPrompt, PROMPT_IDS } from '@magicclass/generation';

describe('slide action narration prompt', () => {
  it('builds a paced, evidence-grounded walkthrough from the supplied slide context', () => {
    const prompt = buildPrompt(PROMPT_IDS.SLIDE_ACTIONS, {
      title: 'Energy Conservation',
      keyPoints: '1. Potential energy converts into kinetic energy.',
      description: 'A formula connects height, mass, and gravitational acceleration.',
      elements: '- id: "formula_1", type: "latex", Formula: "E_p = mgh"',
      courseContext: 'Course Outline: Energy and motion',
      agents: '',
      userProfile: '',
      languageDirective: 'Teach in Chinese.',
    });

    expect(prompt).not.toBeNull();
    expect(prompt!.system).toContain('2-3 spoken beats for a sparse page');
    expect(prompt!.system).toContain('3-5 for a dense page');
    expect(prompt!.system).toContain('35-80 Chinese characters');
    expect(prompt!.system).toContain(
      'Anchor every body segment in a specific phrase, formula, label, or relationship',
    );
    expect(prompt!.system).toContain('do not invent its labels, values, trends, or visual contents');
    expect(prompt!.system).toContain('spotlight or laser immediately before the speech');
    expect(prompt!.user).toContain('formula_1');
    expect(prompt!.user).toContain('E_p = mgh');
    expect(prompt!.user).toContain('Teach in Chinese.');
    expect(`${prompt!.system}\n${prompt!.user}`).not.toMatch(/\{\{\w[\w-]*\}\}/);
  });
});

import { beforeEach, describe, expect, it, vi, type Mock } from 'vitest';
import { generateTTS, TTSInvalidResponseError, TTSRateLimitError } from '@/lib/audio/tts-providers';
import { DEFAULT_TTS_VOICES, TTS_PROVIDERS } from '@/lib/audio/constants';

const mockFetch = vi.hoisted(() => vi.fn() as Mock);
vi.mock('undici', async (importOriginal) => {
  const actual = await importOriginal<typeof import('undici')>();
  return { ...actual, fetch: mockFetch };
});

function wav(): Buffer {
  const bytes = Buffer.alloc(48);
  bytes.write('RIFF', 0, 'ascii');
  bytes.write('WAVE', 8, 'ascii');
  return bytes;
}

describe('MiMo V2.5 TTS', () => {
  beforeEach(() => mockFetch.mockReset());

  it('offers the documented voices before classroom entry', () => {
    expect(TTS_PROVIDERS['mimo-tts'].voices.map((voice) => voice.id)).toEqual([
      '冰糖', '茉莉', '苏打', '白桦', 'Mia', 'Chloe', 'Milo', 'Dean',
    ]);
    expect(DEFAULT_TTS_VOICES['mimo-tts']).toBe('苏打');
  });

  it('sends teacher narration in the assistant message and plays the selected voice', async () => {
    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ choices: [{ message: { audio: { data: wav().toString('base64') } } }] }),
    });

    const result = await generateTTS(
      { providerId: 'mimo-tts', modelId: 'mimo-v2.5-tts', apiKey: 'test-key', voice: '茉莉', speed: 0.8 },
      '看这张幻灯片，我们先理解函数的定义。',
    );

    expect(mockFetch).toHaveBeenCalledWith(
      'https://api.xiaomimimo.com/v1/chat/completions',
      expect.objectContaining({ method: 'POST' }),
    );
    const request = mockFetch.mock.calls[0][1];
    const body = JSON.parse(request.body);
    expect(request.headers.Authorization).toBe('Bearer test-key');
    expect(body).toMatchObject({
      model: 'mimo-v2.5-tts',
      messages: [
        { role: 'user', content: expect.stringContaining('语速稍慢') },
        { role: 'assistant', content: '看这张幻灯片，我们先理解函数的定义。' },
      ],
      audio: { format: 'wav', voice: '茉莉' },
    });
    expect(body.speed).toBeUndefined();
    expect(result.format).toBe('wav');
    expect(Buffer.from(result.audio)).toEqual(wav());
  });

  it('rejects malformed provider audio without creating a playback asset', async () => {
    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ choices: [{ message: { audio: { data: Buffer.from('not audio').toString('base64') } } }] }),
    });
    await expect(generateTTS({ providerId: 'mimo-tts', apiKey: 'test-key', voice: '苏打' }, '讲解')).rejects.toThrow(
      TTSInvalidResponseError,
    );
  });

  it('keeps upstream error bodies private and classifies rate limits', async () => {
    mockFetch.mockResolvedValueOnce({ ok: false, status: 429 });
    await expect(generateTTS({ providerId: 'mimo-tts', apiKey: 'test-key', voice: '苏打' }, '讲解')).rejects.toThrow(
      TTSRateLimitError,
    );
  });
});
